"import pandas as pd
import unicodedata
from collections import Counter

CSV_PATH = r"D:\Anuj\Pearl-ASsignment\amazon-products.csv"
df = pd.read_csv(CSV_PATH, low_memory=False)

text_cols = [c for c in df.columns if df[c].dtype == 'object']

for col in text_cols:
    chars = Counter()
    for val in df[col].dropna():
        for ch in str(val):
            if ord(ch) > 127:
                chars[ch] += 1
    if chars:
        print(f"\n=== Column: {col} (Total non-ascii chars: {sum(chars.values())}) ===")
        # Top 10 non-ascii chars with unicode names
        for ch, cnt in chars.most_common(15):
            name = unicodedata.name(ch, "UNKNOWN")
            print(f"  {repr(ch)} (U+{ord(ch):04X}, {name}): {cnt}")
"
